    text: str,
    start_ms: int | None = None,
    end_ms: int | None = None,
) -> str:
    """解析 JSONL 文本并返回 JSON Lines 输出字符串；非法时抛出 InputError。

    每个非空物理行必须恰好是一个 JSON 对象，且仅含 timestamp_ms、
    temperature、humidity 三个键（缺键、多键、重复键均拒绝）。
    先校验整个文件（区间外的非法记录同样使输入失败），再按区间筛选。
    """
    records: list[tuple[int, int | float, int | float]] = []

    # splitlines 同时识别 \n、\r\n、\r 等物理行分隔；空白行也计入行号。
    for line_no, raw_line in enumerate(text.splitlines(), start=1):
        if not raw_line.strip():
            continue  # 忽略空白行，但其行号已经计入。

        try:
            item = json.loads(raw_line)
        except json.JSONDecodeError as exc:
            raise _jsonl_error(f"JSON 解析失败: {exc.msg}", line_no)
        if not isinstance(item, dict):
            raise _jsonl_error(
                f"每行必须是一个 JSON 对象，实际为 {type(item).__name__}",
                line_no,
            )

        keys = list(item.keys())
        if set(keys) != set(REQUIRED_COLUMNS):
            missing = [k for k in REQUIRED_COLUMNS if k not in keys]
            extra = [k for k in keys if k not in REQUIRED_COLUMNS]
            detail = []
            if missing:
                detail.append(f"缺少键: {', '.join(missing)}")
            if extra:
                detail.append(f"多余键: {', '.join(map(str, extra))}")
            raise _jsonl_error(
                "对象必须恰好包含 timestamp_ms、temperature、humidity 三键（"
                + "；".join(detail)
                + "）",
                line_no,
            )

        timestamp_ms = _jsonl_field_value(
            item, "timestamp_ms", line_no, integer=True
        )
        temperature = _jsonl_field_value(item, "temperature", line_no)
        humidity = _jsonl_field_value(item, "humidity", line_no)
        records.append((timestamp_ms, temperature, humidity))

    return _emit_records(records, start_ms, end_ms)


def _jsonl_field_value(
    item: dict[str, Any],
    column: str,
    line_no: int,
    integer: bool = False,
) -> int | float:
    """提取并校验对象字段：必须是有限 JSON 数值，拒绝字符串/布尔/null。

    integer=True 时额外要求是 JSON 整数字面量（无小数、无指数）。
    """
    value = item[column]
    # bool 是 int 的子类，必须在数值判断之前排除。
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise _jsonl_error(
            f"{column} 必须是 JSON 数值，实际为 "
            f"{_json_type_name(value)}: {json.dumps(value, ensure_ascii=False)}",
            line_no,
        )
    if isinstance(value, float) and not math.isfinite(value):
        # 常规 json.loads 不会产生 NaN/Infinity（会直接解析失败），
        # 此处为防御性校验。
        raise _jsonl_error(f"{column} 必须为有限数值", line_no)
    if integer and not isinstance(value, int):
        raise _jsonl_error(
            f"{column} 必须是 JSON 整数字面量（拒绝小数与指数）: {value}",
            line_no,
        )
    return value


def _json_type_name(value: Any) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "布尔值"
    if isinstance(value, str):
        return "字符串"
    if isinstance(value, (int, float)):
        return "数值"
    if isinstance(value, list):
        return "数组"
    if isinstance(value, dict):
        return "对象"
    return type(value).__name__
